const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const startScreen = document.getElementById('startScreen');
const gameOverScreen = document.getElementById('gameOverScreen');
const startBtn = document.getElementById('startBtn');
const restartBtn = document.getElementById('restartBtn');
const scoreVal = document.getElementById('scoreVal');
const highScoreVal = document.getElementById('highScoreVal');
const finalScore = document.getElementById('finalScore');

// Game state variables
let gameState = 'START'; // START, PLAYING, GAMEOVER
let score = 0;
let highScore = localStorage.getItem('neonRunnerHighScore') || 0;
let gameSpeed = 6;
let spawnTimer = 0;
let spawnInterval = 100;

highScoreVal.textContent = highScore;

// Player object
const player = {
    x: 80,
    y: 300,
    width: 32,
    height: 48,
    dy: 0,
    jumpForce: -11,
    gravity: 0.6,
    grounded: false,
    jumpCount: 0,
    maxJumps: 2,
    color: '#00f2fe'
};

// Arrays for obstacles and particles
let obstacles = [];
let particles = [];
let stars = [];

// Initialize background stars
for (let i = 0; i < 50; i++) {
    stars.push({
        x: Math.random() * canvas.width,
        y: Math.random() * (canvas.height - 50),
        size: Math.random() * 2 + 1,
        speed: Math.random() * 0.5 + 0.2
    });
}

// Input Handlers
function handleJump() {
    if (gameState === 'PLAYING') {
        if (player.grounded || player.jumpCount < player.maxJumps) {
            player.dy = player.jumpForce;
            player.grounded = false;
            player.jumpCount++;
            createJumpParticles();
        }
    }
}

window.addEventListener('keydown', (e) => {
    if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault();
        if (gameState === 'START' || gameState === 'GAMEOVER') {
            startGame();
        } else {
            handleJump();
        }
    }
});

canvas.addEventListener('click', () => {
    if (gameState === 'START' || gameState === 'GAMEOVER') {
        startGame();
    } else {
        handleJump();
    }
});

startBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    startGame();
});

restartBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    startGame();
});

function startGame() {
    gameState = 'PLAYING';
    score = 0;
    gameSpeed = 6;
    spawnTimer = 0;
    spawnInterval = 100;
    obstacles = [];
    particles = [];
    player.y = 300;
    player.dy = 0;
    player.jumpCount = 0;
    player.grounded = true;

    scoreVal.textContent = '0';
    startScreen.classList.add('hidden');
    gameOverScreen.classList.add('hidden');
}

function gameOver() {
    gameState = 'GAMEOVER';
    finalScore.textContent = Math.floor(score);
    if (score > highScore) {
        highScore = Math.floor(score);
        localStorage.setItem('neonRunnerHighScore', highScore);
        highScoreVal.textContent = highScore;
    }
    gameOverScreen.classList.remove('hidden');
}

// Particle effects
function createJumpParticles() {
    for (let i = 0; i < 10; i++) {
        particles.push({
            x: player.x + player.width / 2,
            y: player.y + player.height,
            dx: (Math.random() - 0.5) * 4,
            dy: Math.random() * 2 + 1,
            size: Math.random() * 3 + 1,
            color: '#38bdf8',
            alpha: 1,
            decay: 0.03
        });
    }
}

function createTrailParticles() {
    if (Math.random() < 0.4) {
        particles.push({
            x: player.x,
            y: player.y + Math.random() * player.height,
            dx: -gameSpeed / 2,
            dy: (Math.random() - 0.5) * 0.5,
            size: Math.random() * 2 + 1,
            color: '#00f2fe',
            alpha: 0.8,
            decay: 0.05
        });
    }
}

// Obstacle generation
function spawnObstacle() {
    const types = ['spike', 'tall', 'floating'];
    const type = types[Math.floor(Math.random() * types.length)];

    let obs = {
        x: canvas.width,
        width: 30,
        height: 40,
        y: 308,
        color: '#f43f5e',
        type: type
    };

    if (type === 'tall') {
        obs.height = 65;
        obs.y = 350 - 65;
        obs.color = '#ec4899';
        obs.width = 35;
    } else if (type === 'floating') {
        obs.height = 25;
        obs.width = 40;
        obs.y = 230; // Jump over or duck under / timed jump
        obs.color = '#a855f7';
    } else {
        obs.height = 42;
        obs.y = 350 - 42;
    }

    obstacles.push(obs);
}

// Game Loop Update
function update() {
    if (gameState !== 'PLAYING') return;

    // Increase score & speed over time
    score += 0.1;
    scoreVal.textContent = Math.floor(score);

    if (score % 200 < 0.1) {
        gameSpeed += 0.5;
        spawnInterval = Math.max(45, spawnInterval - 5);
    }

    // Update Player physics
    player.dy += player.gravity;
    player.y += player.dy;

    // Ground collision
    const groundLevel = 350 - player.height;
    if (player.y > groundLevel) {
        player.y = groundLevel;
        player.dy = 0;
        player.grounded = true;
        player.jumpCount = 0;
    }

    createTrailParticles();

    // Spawn obstacles
    spawnTimer++;
    if (spawnTimer >= spawnInterval) {
        spawnObstacle();
        spawnTimer = 0;
        spawnInterval = Math.floor(Math.random() * 40) + 70; // randomize interval
    }

    // Update obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
        let obs = obstacles[i];
        obs.x -= gameSpeed;

        // Collision detection (AABB with slight padding for forgiveness)
        const padding = 6;
        if (
            player.x + padding < obs.x + obs.width - padding &&
            player.x + player.width - padding > obs.x + padding &&
            player.y + padding < obs.y + obs.height - padding &&
            player.y + player.height - padding > obs.y + padding
        ) {
            gameOver();
        }

        // Remove offscreen obstacles
        if (obs.x + obs.width < 0) {
            obstacles.splice(i, 1);
        }
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.x += p.dx;
        p.y += p.dy;
        p.alpha -= p.decay;
        if (p.alpha <= 0) {
            particles.splice(i, 1);
        }
    }

    // Update stars
    for (let star of stars) {
        star.x -= star.speed;
        if (star.x < 0) star.x = canvas.width;
    }
}

// Render Graphics
function draw() {
    // Clear canvas
    ctx.fillStyle = '#020617';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw background stars
    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
    for (let star of stars) {
        ctx.fillRect(star.x, star.y, star.size, star.size);
    }

    // Draw ground grid / neon line
    ctx.strokeStyle = '#38bdf8';
    ctx.lineWidth = 3;
    ctx.shadowColor = '#38bdf8';
    ctx.shadowBlur = 15;
    ctx.beginPath();
    ctx.moveTo(0, 350);
    ctx.lineTo(canvas.width, 350);
    ctx.stroke();

    // Ground fill glow
    ctx.fillStyle = 'rgba(56, 189, 248, 0.05)';
    ctx.fillRect(0, 350, canvas.width, canvas.height - 350);

    // Draw particles
    for (let p of particles) {
        ctx.save();
        ctx.globalAlpha = p.alpha;
        ctx.fillStyle = p.color;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 8;
        ctx.fillRect(p.x, p.y, p.size, p.size);
        ctx.restore();
    }

    // Draw obstacles
    for (let obs of obstacles) {
        ctx.save();
        ctx.fillStyle = obs.color;
        ctx.shadowColor = obs.color;
        ctx.shadowBlur = 12;
        ctx.fillRect(obs.x, obs.y, obs.width, obs.height);

        // Inner detail
        ctx.fillStyle = '#ffffff';
        ctx.globalAlpha = 0.6;
        ctx.fillRect(obs.x + 4, obs.y + 4, obs.width - 8, 4);
        ctx.restore();
    }

    // Draw Player
    ctx.save();
    ctx.fillStyle = player.color;
    ctx.shadowColor = player.color;
    ctx.shadowBlur = 15;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Player visor / face detail
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(player.x + 16, player.y + 10, 10, 6);
    ctx.restore();

    ctx.shadowBlur = 0; // reset shadow
}

// Main Game Loop
function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
}

// Initial draw to show scene before starting
draw();
loop();

