const startBtn = document.getElementById('startBtn');
const restartBtn = document.getElementById('restartBtn');
const scoreVal = document.getElementById('scoreVal');
const highScoreVal = document.getElementById('highScoreVal');
const finalScore = document.getElementById('finalScore');

let score = 0;
let highScore = localStorage.getItem('cyberJumperHighScore') || 0;
highScoreVal.textContent = highScore;

let gameRunning = false;
let gameSpeed = 6;
let gravity = 0.6;

// Player object
const player = {
    x: 100,
    y: 280,
    width: 40,
    height: 50,
    vy: 0,
    jumpForce: -11,
    maxJumps: 2,
    jumpsLeft: 2,
    grounded: false,
    color: '#00f2fe',
    glowColor: 'rgba(0, 242, 254, 0.6)',
    draw() {
        ctx.save();
        // Glow effect
        ctx.shadowBlur = 15;
        ctx.shadowColor = this.glowColor;

        // Draw body
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.width, this.height);

        // Draw visor / eye detail
        ctx.fillStyle = '#0f0c29';
        ctx.fillRect(this.x + 20, this.y + 10, 15, 12);

        // Draw jump particles/indicator if in mid-air and has double jump
        if (!this.grounded && this.jumpsLeft > 0) {
            ctx.fillStyle = '#ff007f';
            ctx.fillRect(this.x + 5, this.y + this.height + 4, this.width - 10, 4);
        }

        ctx.restore();
    },
    jump() {
        if (this.jumpsLeft > 0) {
            this.vy = this.jumpForce;
            this.jumpsLeft--;
            this.grounded = false;

            // Spawn jump particle burst
            createJumpParticles(this.x + this.width / 2, this.y + this.height);
        }
    },
    update() {
        this.vy += gravity;
        this.y += this.vy;

        // Floor collision
        const floorY = 330 - this.height;
        if (this.y >= floorY) {
            this.y = floorY;
            this.vy = 0;
            this.grounded = true;
            this.jumpsLeft = this.maxJumps;
        }
    }
};

// Obstacles array
let obstacles = [];
let particles = [];
let stars = [];

// Initialize background stars
for (let i = 0; i < 50; i++) {
    stars.push({
        x: Math.random() * canvas.width,
        y: Math.random() * (canvas.height - 70),
        size: Math.random() * 2 + 1,
        speed: Math.random() * 0.5 + 0.2
    });
}

function createJumpParticles(x, y) {
    for (let i = 0; i < 8; i++) {
        particles.push({
            x: x,
            y: y,
            vx: (Math.random() - 0.5) * 4,
            vy: Math.random() * -3 - 1,
            size: Math.random() * 4 + 2,
            life: 20,
            color: player.jumpsLeft === 0 ? '#ff007f' : '#00f2fe'
        });
    }
}

function spawnObstacle() {
    const minGap = 90;
    const maxGap = 160;
    const lastObstacle = obstacles[obstacles.length - 1];

    if (!lastObstacle || canvas.width - lastObstacle.x > Math.random() * (maxGap - minGap) + minGap + lastObstacle.width) {
        const type = Math.random();
        let height = Math.floor(Math.random() * 30) + 35; // 35 - 65
        let width = Math.floor(Math.random() * 20) + 25;  // 25 - 45
        let y = 330 - height;

        // Occasional flying drone obstacle
        let isFlying = type > 0.7;
        if (isFlying) {
            y = 330 - height - 80 - Math.random() * 40;
            width = 40;
            height = 25;
        }

        obstacles.push({
            x: canvas.width,
            y: y,
            width: width,
            height: height,
            isFlying: isFlying,
            color: isFlying ? '#ff007f' : '#7f00ff',
            glow: isFlying ? 'rgba(255, 0, 127, 0.6)' : 'rgba(127, 0, 255, 0.6)'
        });
    }
}

function handleInput(e) {
    if (e.code === 'Space' || e.code === 'ArrowUp') {
        if (!gameRunning && startScreen.classList.contains('hidden') === false) {
            startGame();
            e.preventDefault();
        } else if (gameRunning) {
            player.jump();
            e.preventDefault();
        }
    }
}

window.addEventListener('keydown', handleInput);

canvas.addEventListener('click', () => {
    if (!gameRunning && !startScreen.classList.contains('hidden')) {
        startGame();
    } else if (gameRunning) {
        player.jump();
    }
});

startBtn.addEventListener('click', startGame);
restartBtn.addEventListener('click', startGame);

function startGame() {
    score = 0;
    gameSpeed = 6;
    obstacles = [];
    particles = [];
    player.y = 280;
    player.vy = 0;
    player.jumpsLeft = player.maxJumps;
    scoreVal.textContent = score;

    startScreen.classList.add('hidden');
    gameOverScreen.classList.add('hidden');
    gameRunning = true;
}

function gameOver() {
    gameRunning = false;
    if (score > highScore) {
        highScore = Math.floor(score);
        localStorage.setItem('cyberJumperHighScore', highScore);
        highScoreVal.textContent = highScore;
    }
    finalScore.textContent = Math.floor(score);
    gameOverScreen.classList.remove('hidden');
}

function update() {
    if (!gameRunning) return;

    score += 0.1;
    scoreVal.textContent = Math.floor(score);

    // Increase speed gradually
    gameSpeed = 6 + Math.floor(score / 100) * 0.5;

    player.update();

    // Update stars
    stars.forEach(star => {
        star.x -= star.speed;
        if (star.x < 0) star.x = canvas.width;
    });

    // Update obstacles
    spawnObstacle();
    for (let i = obstacles.length - 1; i >= 0; i--) {
        let obs = obstacles[i];
        obs.x -= gameSpeed;

        // Remove offscreen
        if (obs.x + obs.width < 0) {
            obstacles.splice(i, 1);
            continue;
        }

        // AABB Collision Detection
        // Give a slight hitbox leniency for better gameplay feel
        const padding = 6;
        if (
            player.x + padding < obs.x + obs.width - padding &&
            player.x + player.width - padding > obs.x + padding &&
            player.y + padding < obs.y + obs.height - padding &&
            player.y + player.height - padding > obs.y + padding
        ) {
            gameOver();
        }
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life--;
        if (p.life <= 0) {
            particles.splice(i, 1);
        }
    }
}

function draw() {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw background stars
    ctx.fillStyle = '#ffffff';
    stars.forEach(star => {
        ctx.globalAlpha = Math.random() * 0.5 + 0.3;
        ctx.fillRect(star.x, star.y, star.size, star.size);
    });
    ctx.globalAlpha = 1.0;

    // Draw ground line & grid glow
    ctx.save();
    ctx.shadowBlur = 10;
    ctx.shadowColor = '#00f2fe';
    ctx.strokeStyle = '#00f2fe';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, 330);
    ctx.lineTo(canvas.width, 330);
    ctx.stroke();

    // Ground fill
    ctx.fillStyle = 'rgba(0, 242, 254, 0.05)';
    ctx.fillRect(0, 330, canvas.width, canvas.height - 330);
    ctx.restore();

    // Draw obstacles
    obstacles.forEach(obs => {
        ctx.save();
        ctx.shadowBlur = 12;
        ctx.shadowColor = obs.glow;
        ctx.fillStyle = obs.color;
        ctx.fillRect(obs.x, obs.y, obs.width, obs.height);

        // Inner detail
        ctx.fillStyle = '#121222';
        ctx.fillRect(obs.x + 4, obs.y + 4, obs.width - 8, obs.height - 8);
        ctx.restore();
    });

    // Draw particles
    particles.forEach(p => {
        ctx.save();
        ctx.fillStyle = p.color;
        ctx.shadowBlur = 8;
        ctx.shadowColor = p.color;
        ctx.fillRect(p.x, p.y, p.size, p.size);
        ctx.restore();
    });

    // Draw player
    player.draw();
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Initial draw
draw();
requestAnimationFrame(gameLoop);

