            player.x + padding < obs.x + obs.width - padding &&
            player.x + player.width - padding > obs.x + padding &&
            player.y + padding < obs.y + obs.height - padding &&
            player.y + player.height - padding > obs.y + padding
        ) {
            gameOver();
        }
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life--;
        if (p.life <= 0) {
            particles.splice(i, 1);
        }
    }
}

function draw() {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw background stars
    ctx.fillStyle = '#ffffff';
    stars.forEach(star => {
        ctx.globalAlpha = Math.random() * 0.5 + 0.3;
        ctx.fillRect(star.x, star.y, star.size, star.size);
    });
    ctx.globalAlpha = 1.0;

    // Draw ground line & grid glow
    ctx.save();
    ctx.shadowBlur = 10;
    ctx.shadowColor = '#00f2fe';
    ctx.strokeStyle = '#00f2fe';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, 330);
    ctx.lineTo(canvas.width, 330);
    ctx.stroke();

    // Ground fill
    ctx.fillStyle = 'rgba(0, 242, 254, 0.05)';
    ctx.fillRect(0, 330, canvas.width, canvas.height - 330);
    ctx.restore();

    // Draw obstacles
    obstacles.forEach(obs => {
        ctx.save();
        ctx.shadowBlur = 12;
        ctx.shadowColor = obs.glow;
        ctx.fillStyle = obs.color;
        ctx.fillRect(obs.x, obs.y, obs.width, obs.height);

        // Inner detail
        ctx.fillStyle = '#121222';
        ctx.fillRect(obs.x + 4, obs.y + 4, obs.width - 8, obs.height - 8);
        ctx.restore();
    });

    // Draw particles
    particles.forEach(p => {
        ctx.save();
        ctx.fillStyle = p.color;
        ctx.shadowBlur = 8;
        ctx.shadowColor = p.color;
        ctx.fillRect(p.x, p.y, p.size, p.size);
        ctx.restore();
    });

    // Draw player
    player.draw();
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Initial draw
draw();
requestAnimationFrame(gameLoop);

